/**
 * Migration: expected-accounts catalog + bill source column.
 *
 *  1. `expected_accounts` — the catalog of property × service × provider
 *     combos that SHOULD produce one bill per month. Generated by
 *     scripts/build-expected-accounts.mjs, editable by hand.
 *  2. `utility_bills.source` — 'email' (default) | 'manual' | 'qb'.
 *     'qb' rows are bills backfilled from classed QuickBooks Purchases for
 *     accounts that never email (SCE/AT&T/T-Mobile...).
 *
 * Idempotent. Run: node scripts/migrate-expected-accounts.mjs
 */
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import { readFileSync } from 'fs';
import pg from 'pg';

const __dirname = dirname(fileURLToPath(import.meta.url));
for (const line of readFileSync(join(__dirname, '..', '.env.local'), 'utf8').split('\n')) {
  const m = line.match(/^([^#=]+)=(.*?)(?:\s*#.*)?$/);
  if (m) process.env[m[1].trim()] = m[2].trim();
}
const { Pool } = pg;
const pool = new Pool({ connectionString: process.env.DATABASE_URL, ssl: { rejectUnauthorized: false } });

await pool.query(`
  CREATE TABLE IF NOT EXISTS expected_accounts (
    id               SERIAL PRIMARY KEY,
    property_address TEXT NOT NULL,
    unit             TEXT,
    utility_type     TEXT NOT NULL,
    provider         TEXT,            -- canonical: spectrum/sce/ladwp/socalgas/conedison/att/tmobile...
    account_last4    TEXT,
    qb_class_id      TEXT,
    qb_class_name    TEXT,
    typical_amount   NUMERIC(10,2),   -- median of observed amounts
    amount_min       NUMERIC(10,2),
    amount_max       NUMERIC(10,2),
    typical_day      INT,             -- median day-of-month the bill appears
    months_seen      INT,
    last_seen        DATE,
    source           TEXT,            -- 'bills' | 'qb' | 'both'
    active           BOOLEAN NOT NULL DEFAULT true,
    notes            TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
  )
`);
await pool.query(`
  CREATE UNIQUE INDEX IF NOT EXISTS expected_accounts_identity
  ON expected_accounts (property_address, COALESCE(unit, ''), utility_type, COALESCE(provider, ''))
`);
console.log('✓ expected_accounts');

await pool.query(`ALTER TABLE utility_bills ADD COLUMN IF NOT EXISTS source TEXT NOT NULL DEFAULT 'email'`);
console.log('✓ utility_bills.source');

await pool.end();
console.log('Migración completa.');
